"""Render the complete retrospective diagnosis and fixed candidate results."""
from pathlib import Path
import json
import sys
import pandas as pd
import numpy as np
ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'analysis/trade_quality'


def run():
    s=pd.read_csv(OUT/'summary.csv')
    c=pd.read_csv(OUT/'trial_comparison.csv')
    reasons=pd.read_csv(OUT/'by_exit_reason.csv')
    f=pd.read_csv(OUT/'trial_forecast_metrics.csv')
    import matplotlib
    matplotlib.use('Agg')
    import matplotlib.pyplot as plt
    fig,axes=plt.subplots(2,2,figsize=(12,7),sharex='col')
    for j,risk in enumerate(('risk05','risk10')):
        for strategy,color in [('ridge','#b45309'),('trend','#0369a1')]:
            e=pd.read_csv(ROOT/f'artifacts/historical/final/{risk}_base_whole/{strategy}/equity.csv',parse_dates=['date'])
            peaks=np.maximum.accumulate(np.r_[5000,e.equity.to_numpy()])[1:]
            axes[0,j].plot(e.date,e.equity,label=strategy,color=color,lw=1.3)
            axes[1,j].plot(e.date,100*(e.equity.to_numpy()/peaks-1),color=color,lw=1.3)
        axes[0,j].set_title(f'{risk}: original rules, base costs, whole shares')
        axes[0,j].axhline(5000,color='gray',ls=':',lw=1)
        axes[0,j].legend()
        axes[0,j].set_ylabel('Marked equity (USD)')
        axes[1,j].set_ylabel('Drawdown from running peak (%)')
        axes[1,j].tick_params(axis='x',rotation=30)
    fig.tight_layout()
    fig.savefig(OUT/'equity_drawdowns.png',dpi=160)
    plt.close(fig)
    lines=['# تشخيص الصفقات وتجارب التحسين المحدودة','',
        'النتيجة: يوجد سبب لمواصلة بحث Ridge، لكن ليس لاعتماد نسخة محسّنة بعد. اختبار تمديد الاحتفاظ إلى 10 جلسات أعطى تحسنًا متكررًا في الربح مع مخاطرة هبوط أعلى أحيانًا. تقصير تاريخ تدريب Ridge إلى ثلاث سنوات أضعف جودة التوقعات. تمديد احتفاظ البسيطة لم ينجح في التحقق.',
        '', 'هذه دراسة محاكاة برأس مال 5,000 دولار لكل محفظة. الأصل محفوظ دون تعديل. تشخيص النتائج الأصلية يغطي التطوير 2019–2021 والتحقق 2022–2023 والفترة النهائية 2024–2026-10-19. التجارب الجديدة اقتصرت على التطوير والتحقق؛ لم نشغّل المرشحين الجدد على الفترة النهائية. الفترتان قد شوهدتا سابقًا، وبالتالي ليستا اختبارًا جديدًا مستقلًا.',
        '', '## 1. الربح والهبوط وسلاسل الخسائر في الفترة النهائية','',
        'الجدول التالي للتكاليف الأساسية والأسهم الكاملة. الهبوط محسوب من قمم قيمة المحفظة عند الإغلاق، بما فيها رأس المال الابتدائي؛ ليس أقصى هبوط داخل اليوم. مخاطرة الصفقة نسبة قصوى للخسارة المخططة وليست نسبة من رأس المال تُفقد دائمًا، والفجوات قد تتجاوز الوقف.',
        '', '| مخاطرة | الاستراتيجية | صافي الربح $ | أقصى هبوط % | أقصى هبوط $ | أطول سلسلة خسائر | خسارة السلسلة $ | نسبة الفوز % | متوسط الربح $ | متوسط الخسارة $ |',
        '|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    names={'ridge':'Ridge','trend':'البسيطة'}
    for row in s[(s.partition=='final')&s.scenario.str.endswith('base_whole')].itertuples():
        lines.append(f"| {'5%' if row.scenario.startswith('risk05') else '10%'} | {names[row.strategy]} | {row.net_pnl:.2f} | {100*row.max_drawdown:.2f} | {row.max_drawdown_dollars:.2f} | {row.longest_loss_streak} | {row.streak_net_pnl:.2f} | {100*row.win_rate:.2f} | {row.average_win:.2f} | {row.average_loss:.2f} |")
    lines += ['', 'عند 5%، فاز Ridge بنصف الصفقات، لكن متوسط ربحه 65.39 دولار أقل من متوسط خسارته 70.22 دولار؛ هذه العلاقة تفسّر صافي توقعه السلبي لكل صفقة. البسيطة فازت بـ53.74% ومتوسط ربحها أعلى قليلًا من خسارتها.',
        '', 'أطول فترة دون استعادة قمة سابقة: Ridge بلغ 454 جلسة وظل تحت القمة عند نهاية البيانات؛ البسيطة بلغت 144 جلسة واستعادت القمة. الخسائر المتتالية محسوبة بترتيب الخروج المسجل، مع حفظ ترتيب المحرك عند خروج أكثر من صفقة في اليوم نفسه؛ التعادل يقطع السلسلة. طول السلسلة ليس عدد أيام الهبوط، والمراكز المتداخلة ليست رهانات مستقلة.',
        '', '![قيمة المحافظ والهبوط](equity_drawdowns.png)',
        '', '## 2. تشخيص الدخول والخروج، دون تسميته خطأً بأثر رجعي','',
        'الأرقام التالية للسيناريو النهائي 5%، تكاليف أساسية، أسهم كاملة. الربح الخام هو صافي الصفقات نفسها مضافًا إليه عمولاتها واحتكاك التنفيذ المسجل؛ ليس إعادة تشغيل بلا تكاليف.',
        '', '| المقياس | Ridge | البسيطة |','|---|---:|---:|']
    base=s[(s.partition=='final')&(s.scenario=='risk05_base_whole')].set_index('strategy')
    for label,col in [('الصفقات','completed_trades'),('الصفقات الخاسرة صافيًا','losses'),
                      ('الخاسرة حتى قبل التكاليف','gross_losing_trades'),('ربح خام موجب تحول لخسارة بعد التكاليف','cost_flipped_losses'),
                      ('نتيجة خام شبه صفرية تحولت لخسارة بالتكاليف','gross_flat_net_losses'),
                      ('خسرت بعد أن كانت رابحة عند إغلاق سابق','losses_after_positive_close'),
                      ('نتيجة سلبية لو قيس الدخول على خمس جلسات ثابتة دون وقف أو هدف','fixed5_negative_count')]:
        lines.append(f"| {label} | {int(base.loc['ridge',col])} | {int(base.loc['trend',col])} |")
    lines += ['', 'الاحتفاظ الافتراضي لخمس جلسات يستخدم سعر الدخول الفعلي وتكاليف الخروج المفترضة والتوزيعات المستحقة، ويُلغي الوقف والهدف لأغراض التشخيص فقط. لا يعني أن قرار الدخول كان خاطئًا، ولا أنه يمكن تنفيذ تلك النتائج مع قواعد المخاطر الأصلية.',
        '', 'لقياس التراجع داخل الصفقة استخدمنا إغلاقات الجلسات السابقة للخروج ونتيجة الخروج الفعلية، مع استبعاد إغلاق يوم خروج الوقف/الهدف لأنه قد يقع بعد البيع. لذلك قيم MAE/MFE في الملف حدود وصفية على أساس الإغلاقات وليست القمم والقيعان اللحظية. ربح إغلاق سابق لا يعني إمكان بيع الصفقة عند تلك النقطة بمعرفة مسبقة.',
        '', 'كذلك قسنا السعر بعد خمس جلسات من الخروج: تحسن الناتج الافتراضي في 56 من 89 حالة مكتملة لـRidge، و95 من 146 للبسيطة. هذا لا يبرر إلغاء الوقف؛ المقارنة تتجاهل المخاطر والصفقات البديلة والسيولة التي كانت ستُحجز. حالات ما بعد نهاية كل فترة مستبعدة، وليست مفترضة صفرًا.',
        '', '| سبب الخروج، عند 5% | الاستراتيجية | عدد الصفقات | صافي الربح $ |','|---|---|---:|---:|']
    for row in reasons[(reasons.partition=='final')&(reasons.scenario=='risk05_base_whole')].itertuples():
        lines.append(f'| {row.reason} | {names[row.strategy]} | {row.trades} | {row.net_pnl:.2f} |')
    lines += ['', 'في هذا السيناريو لم يصل Ridge إلى هدف الربح أصلًا، والبسيطة سجلت خروج هدف واحدًا. حد الاحتفاظ خمس جلسات بينما الهدف ستة أضعاف ATR؛ هذا يدعم اختبار مدة الاحتفاظ، لكنه لا يثبت وحده أن الهدف أو الوقف خاطئ.',
        '', 'تركيز الأرباح: بعد حذف أفضل خمس صفقات حسابيًا فقط تصبح نتيجة البسيطة −250.97 دولار وRidge −1,006.72 دولار. هذا فحص حساسية، وليس إعادة محاكاة أو دليلًا كافيًا على فساد استراتيجية؛ استراتيجيات الاتجاه قد تعتمد بطبيعتها على قلة من الرابحين.',
        '', '## 3. ما الذي اختبرناه لتحسين الأداء؟','',
        'ثبّتنا [خطة التجربة](EXPERIMENT_PLAN.json) قبل تشغيل المرشحين: ثلاث نسخ تجريبية عبر ثمانية سيناريوهات وفترتين، أي 48 محفظة، بالإضافة إلى أربع إعادات تشغيل مرجعية طابقت الحسابات القديمة. لم نغيّر نسب المخاطرة أو الوقف أو الهدف أو رسوم التداول، ولم نبحث تلقائيًا عن عشرات المعلمات.',
        '', '- ridge_rolling3y: نفس Ridge والمؤشرات والأفق البالغ خمس جلسات، مع تدريب آخر ثلاث سنوات بدل التاريخ المتراكم. الملاءمة ربع سنوية وبفاصل زمني عشر جلسات، ولا يدخل أي عائد لم ينضج قبل حد التدريب. سياسة alpha الأصلية ثابتة: 1 في التطوير و100 في التحقق.',
        '- ridge_hold10: توقعات Ridge القديمة كما هي، وحد الاحتفاظ فقط يصبح عشر جلسات. هذا اختبار قواعد خروج؛ لم ندرّب نموذجًا يتوقع عشرة أيام، وبالتالي عدم تطابق أفق التوقع والخروج باقٍ ويحتاج اختبارًا مستقلًا لاحقًا.',
        '- trend_hold10: قواعد البسيطة ذاتها مع حد احتفاظ عشر جلسات. الوقف والهدف وحدود المخاطرة ما زالت قادرة على إخراج الصفقة مبكرًا.',
        '', 'لتجنب صفقات غير مكتملة، امتنع المرشح ذو مدة عشر جلسات عن الدخول في آخر عشر جلسات من الفترة بدل خمس. لذا النتيجة تشمل أثر مدة الاحتفاظ واختلاف الفرص قرب نهاية الفترة؛ لا نعرضها كتأثير خالص لتأخير مبيعات الصفقات القديمة نفسها.',
        '', 'نتائج 5%، الأسهم الكاملة والتكاليف الأساسية؛ الأرقام أرباح الفترة كاملة وليست شهرية:',
        '', '| الفترة | النسخة | الربح القديم $ | الربح التجريبي $ | الهبوط القديم % | الهبوط التجريبي % | عدد الصفقات التجريبية |','|---|---|---:|---:|---:|---:|---:|']
    for row in c[c.scenario=='risk05_base_whole'].itertuples():
        lines.append(f'| {row.partition} | {row.variant} | {row.net_pnl_baseline:.2f} | {row.net_pnl:.2f} | {100*row.max_drawdown_baseline:.2f} | {100*row.max_drawdown:.2f} | {row.completed_trades} |')
    lines += ['', '## 4. هل التحسن متكرر عبر السيناريوهات؟','',
        '| الفترة | النسخة | تحسن الربح من 8 | قل الهبوط من 8 | تحسن الاثنان من 8 |','|---|---|---:|---:|---:|']
    for (part,variant),g in c.groupby(['partition','variant']):
        lines.append(f'| {part} | {variant} | {int((g.delta_net_pnl>0).sum())} | {int((g.delta_drawdown_pp<0).sum())} | {int(((g.delta_net_pnl>0)&(g.delta_drawdown_pp<0)).sum())} |')
    lines += ['', 'هذه السيناريوهات مترابطة وتستخدم تاريخ الأسعار نفسه، وليست 16 تجربة مستقلة. لا توجد هنا دلالة إحصائية أو ضمان استمرار الربح.',
        '', 'Ridge مع عشر جلسات حسن الربح في جميع السيناريوهات، لكنه زاد الهبوط في 6 من 8 أثناء التطوير و4 من 8 أثناء التحقق. جميع هبوطات التطوير لهذه النسخة تتجاوز بوابة 10% الأصلية. مثال 5% الأساسي حسّن التحقق من 117.50 إلى 291.39 دولار وخفض الهبوط من 12.04% إلى 10.06%، لكنه رفع هبوط التطوير من 13.35% إلى 16.18%. عدد صفقاته في التحقق 17–23 فقط حسب السيناريو، ولا تزال النتائج صغيرة العينة.',
        '', 'Ridge بتاريخ ثلاث سنوات أعطى أرباحًا متفاوتة وأخطاء توقع أعلى. في التحقق زاد MSE من 0.00070932 إلى 0.00073296، وتراجعت دقة الاتجاه من 49.93% إلى 48.63%. تحسن الربح في بعض السيناريوهات لا يعني تحسن النموذج التنبؤي. المقارنة على الصفوف نفسها مع استبعاد العوائد غير الناضجة؛ العوائد متداخلة والأصول مترابطة، فلا نتعامل مع الصفوف كعينات مستقلة.',
        '', 'تمديد احتفاظ البسيطة خفّض ربح التحقق وزاد هبوطه في جميع السيناريوهات؛ نحتفظ بالنسخة الأصلية كمرجع ولا نعتمد التمديد لها.',
        '', '## 5. القرار وما يستحق المتابعة','',
        'لم نعتمد أي مرشح كتغيير دائم أو كتداول حقيقي. أولوية البحث التالية هي مواءمة هدف تنبؤ Ridge مع قرار التداول: مقارنة توقع أفق عشرة أيام أو عائد تحت قواعد الوقف والهدف، مع تقييم الربح الصافي والهبوط معًا. يبقى ridge_hold10 مرشحًا بحثيًا، والبسيطة الأصلية مرجع المقارنة. لا ندمج تعديل مدة الاحتفاظ مع تغيير تدريب Ridge الآن كي لا نفقد تفسير أثر كل تغيير.',
        '', 'قبل أي تجربة لاحقة نثبت قاعدة وهدفًا ومعيار قبول واحدًا، ثم نختبرها على بيانات زمنية لم تدخل في الاختيار أو متابعة ورقية مستقبلية. لا نسمي الفترة النهائية القديمة بيانات جديدة لأنها فُحصت بالفعل. رفع المخاطرة ليس علاجًا؛ عند 10% ارتفع هبوط البسيطة الأساسية من 10.55% إلى 15.38% مع ربح أقل.',
        '', '## 6. التشغيل والتحقق والملفات','',
        '- تشخيص 48 محفظة أصلية و3,684 صفقة؛ طابقت الأرباح ومقاييس الهبوط والفوز ومعامل الربح النتائج المحفوظة.',
        '- 48 محفظة مرشحة + 4 إعادات مرجعية؛ صفر مخالفات في فحوص الحسابات وحدود الدخول القابلة للتحكم. هذا لا يعني عدم إمكان تجاوز وقف بالخسائر الناتجة عن فجوة.',
        '- الاختبارات الجديدة تغطي الهبوط غير المتعافي، رأس المال الابتدائي، سلاسل الخسائر، استبعاد إغلاق يوم الخروج، التوزيعات، نضج الأهداف، وتطهير حدود التدريب. ملف test-results.xml يحتوي الاختبارات المنفذة؛ صحة البرنامج لا تثبت الربحية.',
        '- بصمات الأصل محفوظة في provenance.json؛ المصدر الأصلي والبيانات والتوقعات والنتائج السابقة لم تتغير.',
        '- الصافي بعد تكاليف التداول المفترضة وقبل تكلفة الاستضافة غير المقاسة. لا أوامر حقيقية ولا ربط وسيط.',
        '', '[جميع المقاييس](summary.csv) · [تفاصيل كل صفقة](trade_paths.csv) · [فترات الهبوط والتعافي](drawdown_episodes.csv) · [أسباب الخروج](by_exit_reason.csv) · [تفصيل الأصول](by_asset.csv) · [قرارات القبول والرفض](decisions.csv) · [كل نتائج التحسين](trial_comparison.csv) · [مقاييس التوقع](trial_forecast_metrics.csv)',
        '', 'لإعادة التشغيل من جذر V2 باستخدام البيئة المثبتة:', '', '```bash',
        '.venv/bin/python diagnostics/trade_quality.py',
        '.venv/bin/python diagnostics/improvement_trials.py',
        '.venv/bin/python diagnostics/trade_quality_report.py',
        '.venv/bin/python -m pytest -q diagnostics/test_trade_quality.py diagnostics/test_cost_attribution.py',
        '```']
    count=json.loads((OUT/'provenance.json').read_text())['trades']
    lines=[x.replace('3,684',f'{count:,}') for x in lines]
    (OUT/'REPORT_AR.md').write_text('\n'.join(lines)+'\n')
    print(json.dumps({'report':str(OUT/'REPORT_AR.md'),'diagnosed_trades':count,'trial_runs':len(c)}))

if __name__=='__main__':run()
